//! Embedded static auth pages, their cache validators and browser isolation policy.

use crate::{
    StartupError,
    security::{ApiError, CacheClass, Cached},
};
use axum::{
    http::{HeaderMap, StatusCode, header},
    response::{IntoResponse, Response},
};

// Generated by `build.rs`: `EmbeddedAssets::COUNT` and `EmbeddedAssets::find`.
include!(concat!(env!("OUT_DIR"), "/assets.rs"));

/// Browser isolation policy; `SvelteKit` adds the per-page script hashes in a CSP meta tag.
const CONTENT_SECURITY_POLICY: &str = "frame-ancestors 'none'; object-src 'none'; base-uri 'self'";

/// Failures of embedded browser asset lookup.
#[derive(Debug, thiserror::Error)]
enum AssetError {
    /// No generated page or static file matches the requested path.
    #[error("embedded asset not found")]
    NotFound,
}
impl From<AssetError> for ApiError {
    /// Keeps missing-page replies in the same JSON shape as other browser errors.
    fn from(error: AssetError) -> Self {
        match error {
            AssetError::NotFound => Self::not_found("Not found."),
        }
    }
}

/// One embedded file, with the headers `build.rs` computed for it.
struct Asset {
    /// The file's bytes, from the frontend build.
    bytes: &'static [u8],
    /// `Content-Type`, chosen by extension.
    content_type: &'static str,
    /// Strong validator: base64url of the first 16 bytes of the file's SHA-256, quoted.
    etag: &'static str,
    /// `Immutable` for content-addressed bundles, `Revalidate` for everything else.
    cache: CacheClass,
}

impl Asset {
    /// The file with its headers, or `304 Not Modified` with the same headers and no
    /// body when the request's `If-None-Match` lists this file's tag or `*`
    /// (RFC 9110 §13.1.2, weak comparison).
    fn response(&self, request: &HeaderMap) -> Response {
        let headers = [
            (header::CONTENT_TYPE, self.content_type),
            (header::ETAG, self.etag),
            // SvelteKit emits per-page script hashes in a CSP meta tag; frame-ancestors requires a header.
            (header::CONTENT_SECURITY_POLICY, CONTENT_SECURITY_POLICY),
        ];
        let not_modified = request
            .get_all(header::IF_NONE_MATCH)
            .iter()
            .filter_map(|value| value.to_str().ok())
            .flat_map(|value| value.split(','))
            .map(str::trim)
            .any(|tag| tag == "*" || tag.strip_prefix("W/").unwrap_or(tag) == self.etag);
        if not_modified {
            Cached(self.cache, (StatusCode::NOT_MODIFIED, headers)).into_response()
        } else {
            Cached(self.cache, (headers, self.bytes)).into_response()
        }
    }
}

/// The completed auth frontend embedded in this executable.
pub(crate) struct EmbeddedAssets;
impl EmbeddedAssets {
    /// Rejects executables compiled before the frontend was built.
    /// Tests accept an empty frontend: they build routers but never request a page.
    pub(crate) fn check() -> Result<(), StartupError> {
        if Self::COUNT == 0 && !cfg!(test) {
            Err(StartupError::MissingAssets)
        } else {
            Ok(())
        }
    }

    /// Serves an exact static path or its prerendered HTML page, or `304 Not Modified`
    /// when `request` already holds it.
    pub(crate) fn serve(path: &str, request: &HeaderMap) -> Result<Response, ApiError> {
        let asset = Self::find(path)
            .or_else(|| Self::find(path.trim_end_matches('/')))
            .ok_or(AssetError::NotFound)?;
        Ok(asset.response(request))
    }
}

#[cfg(test)]
mod tests {
    //! Focused coverage of conditional requests.
    use super::*;
    use axum::{body::to_bytes, http::HeaderValue};

    /// A page as `build.rs` would embed it.
    const PAGE: Asset = Asset {
        bytes: b"<!doctype html>",
        content_type: "text/html; charset=utf-8",
        etag: "\"z9yUhWifOIwt0-eFKSC8Fw\"",
        cache: CacheClass::Revalidate,
    };

    /// A matching tag gets a bodiless 304 with the 200's headers; any other gets the file.
    #[tokio::test]
    async fn if_none_match_with_the_tag_is_not_modified() {
        let full = PAGE.response(&HeaderMap::new());
        for (tag, status) in [
            (PAGE.etag, StatusCode::NOT_MODIFIED),
            (
                "\"other\", W/\"z9yUhWifOIwt0-eFKSC8Fw\"",
                StatusCode::NOT_MODIFIED,
            ),
            ("*", StatusCode::NOT_MODIFIED),
            ("\"other\"", StatusCode::OK),
        ] {
            let mut request = HeaderMap::new();
            request.insert(header::IF_NONE_MATCH, HeaderValue::from_static(tag));
            let response = PAGE.response(&request);
            assert_eq!(response.status(), status, "{tag}");
            assert_eq!(response.headers(), full.headers(), "{tag}");
            assert_eq!(
                response.extensions().get::<CacheClass>(),
                Some(&CacheClass::Revalidate)
            );
            let body = to_bytes(response.into_body(), 1024).await.expect("body");
            let expected: &[u8] = if status == StatusCode::OK {
                PAGE.bytes
            } else {
                b""
            };
            assert_eq!(body, expected, "{tag}");
        }
    }
}
